CREATE TABLE IF NOT EXISTS ProcessedMessage (MessageId TEXT NOT NULL PRIMARY KEY, Consumer TEXT NOT NULL, ProcessedUtc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS DimProduct (Sku TEXT NOT NULL PRIMARY KEY, StyleCode TEXT NOT NULL, Name TEXT NOT NULL, Brand TEXT NULL, CategoryCode TEXT NOT NULL, Season TEXT NULL, Colour TEXT NULL, Size TEXT NULL, UpdatedUtc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS DimStore (StoreCode TEXT NOT NULL PRIMARY KEY, Name TEXT NOT NULL, LocationType TEXT NOT NULL, Country TEXT NOT NULL, City TEXT NULL, Currency TEXT NOT NULL, OpenedOn TEXT NOT NULL, ClosedOn TEXT NULL);
CREATE TABLE IF NOT EXISTS FactSales (Id INTEGER PRIMARY KEY AUTOINCREMENT, Channel TEXT NOT NULL, LocationCode TEXT NOT NULL, Market TEXT NOT NULL, BusinessDate TEXT NOT NULL, SourceRef TEXT NOT NULL, Sku TEXT NOT NULL, Quantity INTEGER NOT NULL, NetAmount NUMERIC NOT NULL, NetAmountEur NUMERIC NOT NULL, Currency TEXT NOT NULL, PromotionCode TEXT NULL, Loyalty INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS IX_FactSales_Date ON FactSales (BusinessDate, Channel, LocationCode);
CREATE TABLE IF NOT EXISTS FactWebOrder (OrderId TEXT NOT NULL PRIMARY KEY, OrderNo TEXT NOT NULL, Channel TEXT NOT NULL, Market TEXT NOT NULL, DeliveryMethod TEXT NULL, CollectStoreCode TEXT NULL, Total NUMERIC NOT NULL, TotalEur NUMERIC NOT NULL, Currency TEXT NOT NULL, Lines INTEGER NOT NULL, Status TEXT NOT NULL, CancelReason TEXT NULL, SubmittedUtc TEXT NOT NULL, CompletedUtc TEXT NULL, CancelledUtc TEXT NULL);
CREATE TABLE IF NOT EXISTS FactReturn (Id INTEGER PRIMARY KEY AUTOINCREMENT, RmaNo TEXT NOT NULL, OrderNo TEXT NULL, StoreCode TEXT NULL, Sku TEXT NOT NULL, Quantity INTEGER NOT NULL, Grade TEXT NULL, RefundAmount NUMERIC NOT NULL, RefundAmountEur NUMERIC NOT NULL, Currency TEXT NOT NULL, RefundMethod TEXT NULL, BusinessDate TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS FactStockAlert (Id INTEGER PRIMARY KEY AUTOINCREMENT, LocationCode TEXT NOT NULL, Sku TEXT NOT NULL, OnHand INTEGER NOT NULL, RaisedUtc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ReportRun (Id INTEGER PRIMARY KEY AUTOINCREMENT, ReportName TEXT NOT NULL, BusinessDate TEXT NOT NULL, FileName TEXT NOT NULL, Rows INTEGER NOT NULL, RequestedBy TEXT NULL, CreatedUtc TEXT NOT NULL);
